const body = $input.first().json.body || $input.first().json;
const so = body.salesorder || body;

const customFields = so.custom_fields || [];
function getFieldValue(label) {
  const found = customFields.find(f => (f.label || f.customfield_name) === label);
  return found ? (found.value || found.value_formatted || '') : '';
}

const sessionToken = getFieldValue('Session Token');
const fbclid = getFieldValue('FB Click ID');
const total = parseFloat(so.total || 0);

if (!sessionToken) {
  return [{
    json: {
      valid: false,
      reason: 'Missing Session Token in Sales Order custom fields'
    }
  }];
}

if (total <= 0) {
  return [{
    json: {
      valid: false,
      reason: 'Total amount is zero or negative'
    }
  }];
}

return [{
  json: {
    valid: true,
    salesorder_id: so.salesorder_id || so.salesorder_number,
    customer_id: so.customer_id,
    customer_name: so.customer_name,
    customer_email: so.email || '',
    customer_phone: so.phone || '',
    total: total,
    session_token: sessionToken,
    fbclid: fbclid,
    brand: getFieldValue('Brand') || 'Home Cartel'
  }
}];

const crypto = require('crypto');
const data = $input.first().json;

function sha256(val) {
  if (!val) return '';
  return crypto.createHash('sha256').update(val).digest('hex');
}

function cleanPhone(raw) {
  if (!raw) return '';
  const digits = raw.replace(/\D/g, '');
  if (digits.startsWith('63')) return '+' + digits;
  if (digits.startsWith('09')) return '+63' + digits.slice(1);
  if (digits.startsWith('9') && digits.length === 10) return '+63' + digits;
  return '+' + digits;
}

const normEmail = (data.customer_email || '').trim().toLowerCase();
const normPhone = cleanPhone(data.customer_phone);

const hashedEmail = sha256(normEmail);
const hashedPhone = sha256(normPhone);

const nowMs = Date.now();
const eventTimeSec = Math.floor(nowMs / 1000);
const fbc = data.fbclid ? ('fb.1.' + nowMs + '.' + data.fbclid) : '';

const userData = {};
if (hashedEmail) userData.em = [hashedEmail];
if (hashedPhone) userData.ph = [hashedPhone];
if (fbc) userData.fbc = fbc;

return [{
  json: {
    salesorder_id: data.salesorder_id,
    session_token: data.session_token,
    dataset_id: process.env.META_DATASET_ID,
    access_token: process.env.META_ACCESS_TOKEN,
    payload: {
      data: [{
        event_name: 'Purchase',
        event_time: eventTimeSec,
        action_source: 'system_generated',
        event_id: 'SO-' + data.salesorder_id,
        user_data: userData,
        custom_data: {
          value: data.total,
          currency: 'PHP'
        }
      }]
    }
  }
}];
